/// <summary>
/// MPJ-17981 service class to generate pool specific customer data
/// </summary>
class METCustCustomerPoolService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Generates  pool specific customer data
    /// </summary>
    private void runOperation()
    {
        QueryRun            qr;
        CustCollectionsPool custCollectionsPool;
        CustTable           custTable;
        METCustomerPool     metCustomerpool;
        RecordInsertList    metCustomerpoolList;

        metCustomerpoolList = new RecordInsertList(tableNum(METCustomerPool));

        delete_from metCustomerpool;

        while select  crosscompany custCollectionsPool
        {
            changecompany(custCollectionsPool.DataAreaId)
            {
                Query q = new Query(custCollectionsPool.QueryPacked);
                QueryBuildDataSource qbdsCustTable = q.dataSourceTable(tableNum(CustTable));
                qbdsCustTable.addGroupByAndSelectionField(fieldNum(CustTable, AccountNum));

                qr = new QueryRun(q);

                while(qr.next())
                {
                        custTable = qr.get(tablenum(custTable));

                    metCustomerpool.AccountNum = custTable.AccountNum;
                    metCustomerpool.Description = custCollectionsPool.Description;
                    metCustomerpool.Name = custCollectionsPool.Name;
                    metCustomerpool.Type = custCollectionsPool.Type;
                    metCustomerpool.DataArea = custCollectionsPool.DataAreaId;
                    metCustomerpoolList.add(metCustomerpool);
                }
                metCustomerpoolList.insertDatabase();
            }
        }
    }
